def calculate_average(numbers):
    total = 0
    for n in numbers:
        total += n
    return total / len(numbers)

print(calculate_average([]))

class CustomError(Exception):
    def __init__(self, msg):
        self.msg = msg
        super().__init__(f'Error: {msg}')

def risky(n):
    try:
        if n < 0:
            raise CustomError('منفی شد!')
        if n > 100:
            raise OverflowError()
        return n * 2
    except CustomError as e:
        return str(e)
    except OverflowError:
        return 'زیادی بزرگه'
    finally:
        print(f'پردازش {n} تموم شد')

print(risky(-5))
print(risky(50))
print(risky(200))
